// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0) && actor.code.length == 0 && actor != address(c));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // settle can only run after the guess block; roll forward past it
        vm.roll(block.number + 2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 2)));

        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.settle();

        // Rule: a NON-matching guess must never win the 2-ether prize.
        // Reference C: balance unchanged. Mutant M (== -> !=): pays out 2 ether.
        if (guess != answer) {
            assertTrue(address(c).balance == balBefore);
        }
    }
}
